// Image slots: an unchanged image renders its approved <img> tag byte-for-byte; a replaced image gets
// width/height, WebP variants (same widths as the approved slot) and srcset/sizes generated by the build.
'use strict';
const fs = require('fs');
const path = require('path');
const { getAttr, setAttr, encodeAttr } = require('./html');

const ALLOWED_EXT = /\.(jpe?g|png|webp)$/i;
const MAX_BYTES = 12 * 1024 * 1024;   // uploads above this fail the build with a clear message
const FULL_MAX = 2000;                // replaced images: the full-size copy used by src/lightbox is capped at this width
const DEFAULT_SIZES = '(max-width: 820px) calc(100vw - 48px), 712px';

// Reads width/height from PNG, JPEG or WebP headers (no dependency).
function dimensions(file) {
	const b = fs.readFileSync(file);
	if (b[0] === 0x89 && b[1] === 0x50) return [b.readUInt32BE(16), b.readUInt32BE(20)];
	if (b[0] === 0xff && b[1] === 0xd8) {
		let i = 2;
		while (i < b.length) {
			if (b[i] !== 0xff) { i++; continue; }
			const mk = b[i + 1], len = b.readUInt16BE(i + 2);
			if (mk >= 0xc0 && mk <= 0xcf && ![0xc4, 0xc8, 0xcc].includes(mk)) return [b.readUInt16BE(i + 7), b.readUInt16BE(i + 5)];
			i += 2 + len;
		}
	}
	if (b.toString('ascii', 0, 4) === 'RIFF' && b.toString('ascii', 8, 12) === 'WEBP') {
		const t = b.toString('ascii', 12, 16);
		if (t === 'VP8X') return [1 + b.readUIntLE(24, 3), 1 + b.readUIntLE(27, 3)];
		if (t === 'VP8 ') return [b.readUInt16LE(26) & 0x3fff, b.readUInt16LE(28) & 0x3fff];
		if (t === 'VP8L') { const n = b.readUInt32LE(21); return [(n & 0x3fff) + 1, ((n >> 14) & 0x3fff) + 1]; }
	}
	return null;
}

// Path helpers: content stores site-root paths ("/assets/..."); pages need them relative to their folder.
const toRel = (rootPath, prefix) => prefix + rootPath.replace(/^\//, '');
const variantName = (rootPath, w) => rootPath.replace(/(\.(png|jpe?g|webp))+$/i, '') + '-' + w + '.webp';

// Slot metadata comes from the extractor: originalTag, originalSrc, widths, sizes, dims ('natural' | 'keep').
async function renderSlot(slot, src, alt, ctx) {
	const { prefix, siteRoot, outRoot, generated, errors, sharp } = ctx;
	if (!src) { errors.push(`${ctx.page}: imagem obrigatória ausente (${slot.label})`); return slot.originalTag; }
	if (!alt || !String(alt).trim()) errors.push(`${ctx.page}: texto alternativo (alt) obrigatório ausente (${slot.label})`);
	const srcFile = path.join(siteRoot, decodeURI(src.replace(/^\//, '')));
	if (!ALLOWED_EXT.test(src)) { errors.push(`${ctx.page}: formato de imagem não permitido (${src}) — use JPG, PNG ou WebP`); return slot.originalTag; }
	if (!fs.existsSync(srcFile)) { errors.push(`${ctx.page}: imagem não encontrada (${src})`); return slot.originalTag; }

	let tag;
	if (src === slot.originalSrc) {
		// Approved image: keep the approved tag (srcset, sizes, width/height, loading...) exactly; only alt may change.
		tag = slot.originalTag;
		if (alt !== slot.originalAltDecoded) tag = setAttr(tag, 'alt', encodeAttr(alt, slot.altEntities || {}));
		return tag;
	}
	const size = fs.statSync(srcFile).size;
	if (size > MAX_BYTES) { errors.push(`${ctx.page}: imagem muito grande (${(size / 1048576).toFixed(1)} MB, máximo ${MAX_BYTES / 1048576} MB): ${src}`); return slot.originalTag; }
	const dims = dimensions(srcFile);
	if (!dims) { errors.push(`${ctx.page}: não foi possível ler a imagem (${src})`); return slot.originalTag; }
	if (!sharp) { errors.push(`${ctx.page}: nova imagem requer a dependência "sharp" para gerar as versões WebP (${src})`); return slot.originalTag; }

	// Each slot keeps the character it has in the approved site:
	// - approved tag WITHOUT srcset (e.g. inline-lightbox galleries, whose script opens img.currentSrc): no srcset,
	//   src = full-size image (capped) so the lightbox keeps opening the large picture;
	// - approved tag WITH srcset: WebP variants at the same widths + the approved sizes.
	// Widths come from the approved srcset descriptors, whatever the file naming (WebP variants or WordPress sizes).
	const approvedSrcset = getAttr(slot.originalTag, 'srcset');
	const responsive = !!approvedSrcset;
	const approvedWidths = responsive ? [...new Set(approvedSrcset.split(',').map((c) => parseInt((c.trim().split(/\s+/)[1] || '').replace('w', ''), 10)).filter((n) => n > 0))].sort((a, b) => a - b) : [];
	const widths = approvedWidths.filter((w) => w < dims[0]);
	const variants = [];
	for (const w of responsive ? (widths.length ? widths : [Math.min(dims[0], FULL_MAX)]) : []) {
		const rel = variantName(src, w);
		const out = path.join(outRoot, rel.replace(/^\//, ''));
		if (!fs.existsSync(path.join(siteRoot, rel.replace(/^\//, ''))) && !generated.has(out)) {
			fs.mkdirSync(path.dirname(out), { recursive: true });
			await sharp(srcFile).rotate().resize({ width: w, withoutEnlargement: true }).webp({ quality: 86 }).toFile(out);
			generated.add(out);
		}
		variants.push([rel, w]);
	}
	let fullRel = src;
	if (dims[0] > FULL_MAX) {
		fullRel = variantName(src, FULL_MAX);
		const out = path.join(outRoot, fullRel.replace(/^\//, ''));
		if (!generated.has(out)) { fs.mkdirSync(path.dirname(out), { recursive: true }); await sharp(srcFile).rotate().resize({ width: FULL_MAX }).webp({ quality: 88 }).toFile(out); generated.add(out); }
	}
	const fullDims = dims[0] > FULL_MAX ? [FULL_MAX, Math.round(dims[1] * FULL_MAX / dims[0])] : dims;
	tag = slot.originalTag;
	tag = setAttr(tag, 'src', encodeAttr(toRel(fullRel, prefix)));
	tag = setAttr(tag, 'alt', encodeAttr(alt));
	if (responsive) {
		tag = setAttr(tag, 'srcset', variants.map(([r, w]) => encodeAttr(toRel(r, prefix)) + ' ' + w + 'w').join(', '));
		tag = setAttr(tag, 'sizes', encodeAttr(slot.sizes || DEFAULT_SIZES));
	}
	if (slot.dims !== 'keep' && getAttr(tag, 'width') !== null) { tag = setAttr(tag, 'width', String(fullDims[0])); tag = setAttr(tag, 'height', String(fullDims[1])); }
	if (slot.dims !== 'keep' && getAttr(tag, 'width') === null) { tag = setAttr(tag, 'width', String(fullDims[0])); tag = setAttr(tag, 'height', String(fullDims[1])); }
	return tag;
}

// Elementor lightbox hash on Home carousel slides: base64 JSON {"id":..,"url":"..","slideshow":".."}, URL-encoded.
function elementorHash(originalHash, newUrlRel) {
	const prefix = '#elementor-action%3Aaction%3Dlightbox%26settings%3D';
	const json = JSON.parse(Buffer.from(decodeURIComponent(originalHash.slice(prefix.length)), 'base64').toString('utf8'));
	json.url = newUrlRel;
	return prefix + encodeURIComponent(Buffer.from(JSON.stringify(json), 'utf8').toString('base64'));
}

module.exports = { renderSlot, dimensions, elementorHash, toRel, ALLOWED_EXT, MAX_BYTES };
